import { Effect } from "effect"

interface Account {
  readonly name: string
  readonly country: string
}

interface Usage {
  readonly storageGb: number
  readonly requests: number
}

interface Rates {
  readonly storagePerGb: number
  readonly requestPrice: number
}

export interface BillingReader {
  readonly getAccount: (id: string) => Effect.Effect<Account, Error>
  readonly getUsage: (id: string) => Effect.Effect<Usage, Error>
  readonly getRates: () => Effect.Effect<Rates, Error>
  readonly getTaxRate: (country: string) => Effect.Effect<number, Error>
}

export const buildBillingPreview = (reader: BillingReader, accountId: string) =>
  Effect.gen(function*() {
    const [account, usage, rates] = yield* Effect.all(
      [reader.getAccount(accountId), reader.getUsage(accountId), reader.getRates()],
      { concurrency: "unbounded" }
    )
    const taxRate = yield* reader.getTaxRate(account.country)

    const subtotal =
      usage.storageGb * rates.storagePerGb +
      usage.requests * rates.requestPrice
    const tax = subtotal * taxRate

    return {
      accountId,
      accountName: account.name,
      subtotal,
      tax,
      total: subtotal + tax
    }
  })
